{
    "name": "My Custom Report",
    "report_type": "student_report",
    "template_config": {
        "include_grades": true,
        "include_attendance": true,
        "include_payments": false
    },
    "is_default": false,
    "is_active": true
}

{
    "name": "إشعار الغياب المتكرر",
    "description": "إرسال إشعار للأهل عند غياب الطالب 3 أيام متتالية",
    "rule_type": "attendance",
    "trigger_event": "student_absent",
    "conditions": {
        "consecutive_absences": {
            "operator": "greater_than",
            "value": 3
        }
    },
    "actions": [
        {
            "type": "send_notification",
            "recipient_type": "parent",
            "title": "تنبيه غياب",
            "message": "الطالب {student_name} غائب منذ {consecutive_absences} أيام"
        },
        {
            "type": "create_alert",
            "severity": "high",
            "message": "غياب متكرر: {student_name}"
        }
    ],
    "priority": 1,
    "is_active": true
}

{
    "name": "قواعد الحضور",
    "description": "مجموعة القواعد المتعلقة بالحضور والغياب",
    "execution_order": "sequential",
    "is_active": true
}
